function volunteerSection(){return `<section class="section" id="volunteer">${communityHeading(tr('One pool. Many ways to help.','قائمة واحدة. وفرص كثيرة للمشاركة.'),tr('Volunteer with SSO.','تطوّع مع المنظمة.'),tr('Introduce yourself, then join the volunteer WhatsApp group. Opportunities and shift signups happen inside the group.','عرّف بنفسك ثم انضم لمجموعة المتطوعين على واتساب. تُنشر الفرص ويُسجّل للمهام داخل المجموعة.'))}<p class="demo-notice">${tr('Volunteer registration opens soon. The group invitation is not available yet.','التسجيل للتطوع يُفتح قريباً. دعوة المجموعة غير متاحة بعد.')}</p><div class="community-two"><div><h3>${tr('The group is the pool.','المجموعة هي قائمة المتطوعين.')}</h3><ol class="volunteer-steps"><li>${tr('Enter your name and email below.','أدخل اسمك وبريدك الإلكتروني.')}</li><li>${tr('When registration opens, the group link appears here after you complete the form.','عند فتح التسجيل يظهر رابط المجموعة هنا بعد إكمال النموذج.')}</li><li>${tr('Join the group to enter the pool. The form alone does not make you a member. Leaving the group means leaving the pool.','انضم للمجموعة لدخول القائمة. النموذج وحده لا يجعلك عضواً. مغادرة المجموعة تعني مغادرة القائمة.')}</li></ol><p>${tr('WhatsApp is required for all volunteers. Choose the opportunities that suit you; joining does not commit you to every event.','واتساب مطلوب لجميع المتطوعين. اختر الفرص المناسبة لك؛ الانضمام لا يلزمك بكل فعالية.')}</p></div><div class="community-card"><form class="demo-form" id="volunteer-form"><span class="tag">${tr('JOIN THE VOLUNTEER POOL','انضم لقائمة المتطوعين')}</span><label for="volunteer-name">${tr('Name','الاسم')}</label><input id="volunteer-name" required maxlength="80" autocomplete="name"><label for="volunteer-email">${tr('Email','البريد الإلكتروني')}</label><input id="volunteer-email" type="email" required maxlength="254" autocomplete="email"><label class="volunteer-check"><input type="checkbox" id="volunteer-whatsapp" required><span>${tr('I understand that WhatsApp is required to enter the volunteer pool and my phone number will be visible to other group members.','أفهم أن واتساب مطلوب لدخول قائمة المتطوعين وأن رقم هاتفي سيكون ظاهراً لأعضاء المجموعة.')}</span></label><button class="button">${tr('Continue to WhatsApp','متابعة إلى واتساب')} </button></form><div id="volunteer-review" hidden tabindex="-1"></div><p id="volunteer-status" role="status"></p></div></div></section>`}
function bindVolunteer(){const f=document.querySelector('#volunteer-form'),review=document.querySelector('#volunteer-review'),status=document.querySelector('#volunteer-status');f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;const name=document.querySelector('#volunteer-name');if(!name.value.trim()){name.setCustomValidity(tr('Enter your name.','اكتب اسمك.'));name.reportValidity();name.oninput=()=>name.setCustomValidity('');return}f.hidden=true;review.hidden=false;review.innerHTML=`<span class="tag">${tr('YOUR NEXT STEP','خطوتك التالية')}</span><h3>${tr('Join SSO Volunteers.','انضم لمتطوعي المنظمة.')}</h3><p>${tr('Ahlan','أهلاً')} ${escapeOnboard(name.value.trim())}. ${tr('Join the WhatsApp group to enter the pool and see volunteer opportunities.','انضم لمجموعة واتساب لدخول القائمة واستعراض فرص التطوع.')}</p><button type="button" class="button" id="volunteer-join">${tr('WhatsApp group · coming soon','مجموعة واتساب · قريباً')} </button><p class="small-note">${tr('The invitation is not available yet. Your details have not been submitted. Check back when registration opens.','الدعوة غير متاحة بعد. لم تُرسل بياناتك. عد عند فتح التسجيل.')}</p><button type="button" class="textlink" id="volunteer-again">${tr('Start over','البدء من جديد')}</button>`;review.focus();document.querySelector('#volunteer-join').onclick=()=>{status.textContent=tr('The group invitation is coming soon. You have not joined the volunteer pool.','دعوة المجموعة متاحة قريباً. لم تنضم لقائمة المتطوعين.')};document.querySelector('#volunteer-again').onclick=()=>{review.hidden=true;review.innerHTML='';f.hidden=false;f.reset();status.textContent='';name.focus()}}}
